/** Other names the same brand goes by: an engine's `type`, a product's name, a server's name. */
const ALSO: Record<string, string> = {
  postgres: "postgresql", gsheets: "googlesheets", microsoftteams: "teams", msteams: "teams", microsoftoutlook: "outlook",
  microsoftonedrive: "onedrive", outlookmail: "outlook", amazons3: "s3", googlebigquery: "bigquery", amazonredshift: "redshift",
  cockroach: "cockroachdb", timescale: "timescaledb", apachedruid: "druid", apachehive: "hive", apachespark: "spark", sparksql: "spark",
  aurorapostgresql: "postgresql", auroramysql: "mysql", saphana: "sap", hana: "sap", sapsybase: "sap",
};

/** The mark for a name however it is written ("Google Drive comments", "bigquery"), or null when none is held. */
export function brandMark(name: string): BrandMark | null {
  const key = name.toLowerCase().replace(/[^a-z0-9]/g, "");
  const exact = BRAND_MARKS[ALSO[key] ?? key];
  if (exact) return exact;
  const prefix = Object.keys(BRAND_MARKS).filter(k => key.startsWith(k)).sort((a, b) => b.length - a.length)[0];
  return prefix ? BRAND_MARKS[prefix] : null;
}
